-- The onboarding template, as Postgres tables. Made by baseToSql (@svgrid/enterprise/base);
-- the svgrid: comments keep what SQL has no type for, so baseFromDatabase opens it as the same base.

create table "people" (
  "id" text primary key default gen_random_uuid()::text,
  "name" text,
  "photo" jsonb,
  "status" text,
  "role" text,
  "department_id" text,
  "start" date,
  "manager" text,
  "email" text
);
create table "checklist" (
  "id" text primary key default gen_random_uuid()::text,
  "item" text,
  "person_id" text,
  "owner" text,
  "due" date,
  "done" boolean
);
create table "departments" (
  "id" text primary key default gen_random_uuid()::text,
  "department" text,
  "head" text
);

comment on column "people"."name" is 'svgrid:{"field":"name","header":"Name","width":190,"fieldType":"text"}';
